    {
        "name": "Sendai Virus Infection",
        "name_ja": "センダイウイルス感染症",
        "symptoms": {"sneezing", "nasal_discharge", "labored_breathing", "lethargy", "rough_coat"},
        "description": "上気道感染によるくしゃみや鼻水。",
        "description_ja": "重度の肺炎を引き起こすことがある呼吸器ウイルス。",
        "urgency": "high",
        "recommended_tests": ["serology", "pcr_test"],
        "causes": "Hamsterにおける上部気道感染症（Hamster）の原因: ハムスターにおける細菌性の呼吸器系疾患。上部気道感染症は適切な診断と治療管理が重要である。早期発見と適切な介入が予後改善の鍵となる。",
        "causes_ja": "Hamsterにおけるセンダイウイルス感染症（Hamster）の原因: ウイルス病原体による感染。直接接触、飛沫・空気感染、媒介物、ベクター媒介が感染経路。免疫抑制、ストレス、過密飼育、ワクチン未接種が感受性を高める。",
        "pathophysiology": "上部気道感染症（Hamster）はHamsterにおける呼吸器疾患である。気道、肺実質、または胸膜腔の炎症、閉塞、または機能障害を伴う。ガス交換の障害により低酸素血症および高炭酸ガス血症の可能性がある。炎症性滲出液、粘液蓄積、構造変化が有効な換気を低下させる。代償性頻呼吸により呼吸仕事量と代謝要求が増加する。重症例は呼吸不全に進行し緊急介入が必要となりうる。",
        "pathophysiology_ja": "センダイウイルス感染症（Hamster）はHamsterにおけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Hamsterにおける上部気道感染症（Hamster）の治療は原因への対処、適切な支持療法、臨床徴候の管理を行う。種に適した薬物療法、食事の最適化、環境調整が主要な治療要素である。定期的なフォローアップにより治療効果を確認し用量調整を行う。",
        "treatment_ja": "Hamsterにおけるセンダイウイルス感染症（Hamster）の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "上部気道感染症（Hamster）の予防には適切な飼育管理、種に合ったバランスの取れた栄養、定期的な健康診断、ストレスの最小化、清潔な生活環境の維持、初期臨床徴候への迅速な対応が含まれる。",
        "prevention_ja": "センダイウイルス感染症（Hamster）の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "センダイウイルス感染症（Hamster）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
