    {
        "name": "Stroke",
        "name_ja": "脳卒中",
        "symptoms": {"head_tilt", "circling", "loss_of_balance", "paralysis", "disorientation"},
        "description": "ビタミン欠乏と運動不足による後肢麻痺。",
        "description_ja": "脳への血液供給の途絶で、高齢ハムスターに多い。",
        "urgency": "emergency",
        "recommended_tests": ["neurological_exam", "physical_exam"],
        "causes": "Disruption of blood supply to the brain, more common in older hamsters.",
        "causes_ja": "Hamsterにおける脳卒中の原因: 脳への血液供給の途絶で、高齢ハムスターに多い。",
        "pathophysiology": "Stroke is a traumatic/mechanical condition in Hamster. Disruption of blood supply to the brain, more common in older hamsters. Tissue damage results from external mechanical forces exceeding the structural tolerance of affected tissues. The injury triggers an acute inflammatory cascade with hemorrhage, edema, and pain. Depending on severity, there may be disruption of vascular supply leading to ischemia, contamination with environmental organisms leading to infection, and progressive tissue necrosis. The healing response involves hemostasis, inflammation, proliferation, and remodeling phases.",
        "pathophysiology_ja": "脳卒中はHamsterにおける外傷性・機械的疾患である。罹患組織の構造的耐性を超える外部機械的力により組織損傷が生じる。損傷は出血、浮腫、疼痛を伴う急性炎症カスケードを惹起する。重症度に応じて、血管供給の途絶による虚血、環境微生物による汚染、進行性の組織壊死が生じうる。治癒過程は止血、炎症、増殖、リモデリングの各段階を経る。",
        "treatment": "Treatment of stroke in hamster prioritizes stabilization, pain management, and wound care. Assess and address life-threatening injuries first (airway, breathing, circulation). Analgesia is essential—use species-appropriate agents (NSAIDs, opioids, local anesthetics). Clean and debride wounds; primary closure, second-intention healing, or reconstructive surgery as indicated. Broad-spectrum antibiotics for contaminated wounds. Splinting or surgical fixation for fractures. Monitor for delayed complications.",
        "treatment_ja": "Hamsterにおける脳卒中の治療は安定化、疼痛管理、創傷ケアを優先する。生命を脅かす損傷を最初に評価・対処する（気道、呼吸、循環）。種に適した鎮痛薬（NSAIDs、オピオイド、局所麻酔薬）による鎮痛が不可欠である。創傷を洗浄・デブリードマンし、一次閉鎖、二次治癒、再建手術を適宜行う。汚染創には広域抗菌薬を使用する。骨折には副子固定または外科的固定を行う。遅発性合併症をモニタリングする。",
        "prevention": "脳卒中の予防には安全で種に適した飼育環境の整備、鋭利物・危険物の除去、適切な取り扱い技術、他の動物との接触時の監視、温度管理、落下防止策が含まれる。",
        "prevention_ja": "脳卒中の予防には安全で種に適した飼育環境の整備、鋭利物・危険物の除去、適切な取り扱い技術、他の動物との接触時の監視、温度管理、落下防止策が含まれる。",
        "prognosis": "",
        "prognosis_ja": "脳卒中の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
